import 'package:flutter/material.dart';
import '../../core/data/customer_repository.dart';
import '../../shared/irkop_ui.dart';
class CustomersPage extends StatefulWidget{const CustomersPage({super.key,this.businessId});final String? businessId;@override State<CustomersPage> createState()=>_CustomersPageState();}
class _CustomersPageState extends State<CustomersPage>{final _repo=CustomerRepository();late Future<List<Customer>> _future;String _query='';@override void initState(){super.initState();_future=widget.businessId==null?Future.value(const []):_repo.loadCustomers(widget.businessId!);}
@override Widget build(BuildContext context)=>FutureBuilder<List<Customer>>(future:_future,builder:(context,s){final data=(s.data??const <Customer>[]).where((c)=>c.name.toLowerCase().contains(_query.toLowerCase())||(c.phone??'').contains(_query)).toList();return ListView(padding:const EdgeInsets.all(16),children:[const IrkopSectionHeader(eyebrow:'Pelanggan',title:'Data Pelanggan',subtitle:'Cari dan kelola pelanggan.',icon:Icons.people_outline,action:'Database'),const SizedBox(height:14),TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari pelanggan atau nomor',border:OutlineInputBorder()),onChanged:(v)=>setState(()=>_query=v)),const SizedBox(height:12),if(s.connectionState!=ConnectionState.done)const Center(child:Padding(padding:EdgeInsets.all(32),child:CircularProgressIndicator())),if(s.hasError)Text('Gagal memuat: '+s.error.toString()),if(s.connectionState==ConnectionState.done&&!s.hasError&&data.isEmpty)const EmptyStateCard(icon:Icons.people_outline,title:'Belum ada pelanggan',subtitle:'Tambahkan pelanggan baru.'),...data.map((c)=>Card(child:ListTile(leading:CircleAvatar(child:Text(c.name.isEmpty?'P':c.name[0].toUpperCase())),title:Text(c.name),subtitle:Text((c.phone??'').isEmpty?'Tanpa nomor telepon':c.phone!))))]);});}